function [d] = main_lines(jd_tt)
%MAIN_LINES  oceantides.mainLines(jd_tt): the degree-2 corrections of the eight main lines, dC += Cp cos th + Sp sin th,
%   dS += Sp cos th - Cp sin th (Cp, Sp in units of 1e-11).
%   jd_tt: real[1] (passed a plain number)
%   returns d: Dcs5 (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    d = asils.models.solidtides.Dcs5_zero();
    beta = asils.models.oceantides.doodson(jd_tt);
    d = asils.models.solidtides.Dcs5_zero();
    for i = (0):((8) - 1)
        deg = fix(asils.models.tidelines.OCEAN_MAIN_LINES((i) + 1, 7));
        m = fix(asils.models.tidelines.OCEAN_MAIN_LINES((i) + 1, 8));
        cp = (asils.models.tidelines.OCEAN_MAIN_LINES((i) + 1, 9) * 1e-11);
        sp = (asils.models.tidelines.OCEAN_MAIN_LINES((i) + 1, 10) * 1e-11);
        th = 0;
        for k = (0):((6) - 1)
            th = (th + (asils.models.tidelines.OCEAN_MAIN_LINES((i) + 1, (k) + 1) * beta((k) + 1)));
        end
        st = sin(th);
        ct = cos(th);
        d.dc((deg) + 1, (m) + 1) = (d.dc((deg) + 1, (m) + 1) + ((cp * ct) + (sp * st)));
        d.ds((deg) + 1, (m) + 1) = (d.ds((deg) + 1, (m) + 1) + ((sp * ct) - (cp * st)));
    end
end
